Problem:
A company wants to advertise its product. They want to use three types of ads: magazine ads, flyers, and billboard ads. The cost for each option along with the expected viewership is given. A magazine ad costs $1000 and attracts 10000 viewers. A flyer costs $200 and attracts 5000 viewers. A billboard ad costs $7000 and attracts 25000 viewers. To avoid annoying customers, the city has limited the number of flyers from a single company to 8. In addition, at most a third of the total number of ads should be billboard ads and at least 15% of the ads should be magazine ads. If the weekly budget is $50000, how many ads of each type should be run in order to maximize the number of viewers?

Model and facts:
{
 "model": {
  "variables": [
   {
    "name": "magazine ads",
    "lower": 0.0,
    "upper": null,
    "integer": true
   },
   {
    "name": "flyers",
    "lower": 0.0,
    "upper": null,
    "integer": true
   },
   {
    "name": "billboard ads",
    "lower": 0.0,
    "upper": null,
    "integer": true
   }
  ],
  "objective": {
   "sense": "max",
   "terms": [
    {
     "var": "magazine ads",
     "coef": 10000.0
    },
    {
     "var": "flyers",
     "coef": 5000.0
    },
    {
     "var": "billboard ads",
     "coef": 25000.0
    }
   ]
  },
  "constraints": [
   {
    "name": "budget",
    "terms": [
     {
      "var": "magazine ads",
      "coef": 1000.0
     },
     {
      "var": "flyers",
      "coef": 200.0
     },
     {
      "var": "billboard ads",
      "coef": 7000.0
     }
    ],
    "sense": "<=",
    "rhs": 50000.0
   },
   {
    "name": "flyer_limit",
    "terms": [
     {
      "var": "flyers",
      "coef": 1.0
     }
    ],
    "sense": "<=",
    "rhs": 8.0
   },
   {
    "name": "billboard_share",
    "terms": [
     {
      "var": "billboard ads",
      "coef": 2.0
     },
     {
      "var": "magazine ads",
      "coef": -1.0
     },
     {
      "var": "flyers",
      "coef": -1.0
     }
    ],
    "sense": "<=",
    "rhs": 0.0
   },
   {
    "name": "magazine_share",
    "terms": [
     {
      "var": "magazine ads",
      "coef": 0.85
     },
     {
      "var": "flyers",
      "coef": -0.15
     },
     {
      "var": "billboard ads",
      "coef": -0.15
     }
    ],
    "sense": ">=",
    "rhs": 0.0
   }
  ]
 },
 "facts": {
  "objective": 520000.0,
  "values": {
   "magazine ads": 48.0,
   "flyers": 8.0,
   "billboard ads": 0.0
  },
  "binding": [
   "flyer_limit"
  ],
  "slack": {
   "budget": 400.0,
   "flyer_limit": 0.0,
   "billboard_share": 56.0,
   "magazine_share": 39.6
  },
  "shadow_prices": null
 }
}
